class Rec:
    def __init__(self, n):
        self.n = n
        self.i = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.i >= self.n:
            raise StopIteration
        self.i += 1
        return self.i
a = Rec(100)
b = Rec(100)
it = sol.round_robin([a, b])
first = [next(it), next(it), next(it)]
result = (first, a.i, b.i)

class Fuse:
    def __init__(self, limit):
        self.limit = limit
        self.calls = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.calls >= self.limit:
            raise RuntimeError('over-advanced')
        self.calls += 1
        return self.calls * 10
import itertools
f = Fuse(3)
result = list(itertools.islice(sol.round_robin([f]), 3))
